'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='prompt-lab-v1';
let saved={cases:{},draft:null}, storageOK=true;
try{const v=JSON.parse(localStorage.getItem(KEY)||'null');if(v&&typeof v==='object'&&v.cases&&typeof v.cases==='object')saved=v;}catch(e){storageOK=false;}
let page='course',current=0,stage=0,prediction='',guesses=[[],[]],shown=false;
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));storageOK=true;return true;}catch(e){storageOK=false;notify('브라우저 저장이 제한됐습니다. 학습 기록을 파일로 내려받으세요.');return false;}}
function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function analyze(text,original=false){
 const raw=String(text||'').replace(/\r\n?/g,'\n'),marks=/^[▶■#\-※]/,end=/[.!?]['")\]]*$/;
 const clean=l=>l.trim().replace(/\*\*/g,'');
 let uncertain=false;
 const split=l=>{
   let v=clean(l);if(!v||marks.test(v))return [];
   if(!original)v=v.replace(/(^|\s)([QA])\.\s*/g,'$1$2: ');
   if(!end.test(v)){if(!original)uncertain=true;return [];}
   return v.split(/(?<=[.!?])\s+/).filter(x=>x.trim());
 };
 const blocks=raw.trim().split(/\n\s*\n/).map(b=>b.split('\n').flatMap(split)).filter(b=>b.length);
 const sentences=blocks.flat();
 const headers=raw.split('\n').filter(l=>clean(l).replace(/^[-*•· ]+/,'').startsWith('▶')).length;
 const strip=s=>s.replace(/[.!?'")\]\s]+$/g,'');
 const flags=[headers===4,blocks.length===4,!!blocks[0]&&blocks[0].length===2,(raw.match(/!/g)||[]).length===1,blocks.length>0&&blocks.every(b=>b.length>=2&&b.length<=4),sentences.length>=10&&sentences.length<=14,sentences.length>0&&sentences.every(s=>strip(s).endsWith('요')),!!sentences[0]&&Array.from(sentences[0]).length<=20];
 if(!original&&uncertain)[1,2,4,5,6,7].forEach(i=>flags[i]=null);
 return {flags,headers,blocks:blocks.length,sentences:sentences.length,firstLength:sentences[0]?Array.from(sentences[0]).length:0,uncertain};
}
function hero(kicker,title,description){return `<section class="hero"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="muted">${description}</p></div></section>`;}
function render(){
 document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 if(page==='experiment')renderExperiment();if(page==='course')renderCourse();if(page==='assessment')renderAssessment();if(page==='lab')renderLab();if(page==='editor')renderEditor();if(page==='records')renderRecords();if(page==='about')renderAbout();
}
function go(p){if(typeof logLearning==='function'&&['lab','editor','about'].includes(p))logLearning('reference-open',{page:p});page=p;render();window.scrollTo({top:0,behavior:'instant'});}
function renderLab(){const c=DATA.cases[current];
 $('#main').innerHTML=hero('실제 응답 비교하기','좋은 예시가 항상 좋은 결과를 낼까요?','논문에 쓰인 실제 응답을 나란히 읽어 보세요. 예시나 빈 틀을 넣었을 때 무엇이 달라졌는지, 지시와 어긋나는 부분은 없는지 확인합니다.')+
 `<p class="note">기반 논문 · ${esc(DATA.title)}</p><div class="steps"><span>01 예상하기</span><span>02 비교하기</span><span>03 적용하기</span></div><div class="layout"><aside class="side" aria-label="사례 선택">${DATA.cases.map((x,i)=>`<button class="case ${i===current?'active':''}" data-case="${i}" aria-current="${i===current?'step':'false'}"><b>0${i+1}</b><span>${esc(x.taskName)}<small>${x.items[0].condition} ↔ ${x.items[1].condition}${saved.cases[x.id]?' · 기록됨':''}</small></span></button>`).join('')}</aside><section><div class="card"><span class="tag">CASE 0${c.id}</span><span class="tag">${esc(c.items[0].model)}</span><h2>${esc(c.taskName)}</h2><p>${esc(c.intro)}</p><details><summary>공통 요구사항 8개 보기</summary><ol>${DATA.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ol></details><div class="pair">${c.items.map((x,i)=>`<div><h3>${i?'B':'A'} · ${esc(x.name)}</h3><details><summary>실제 입력 프롬프트 읽기</summary><pre class="prompt">${esc(x.prompt)}</pre></details></div>`).join('')}</div><h3>어느 응답이 조건을 더 많이 지킬까요?</h3><div class="choices">${[['A','A가 더 많이'],['same','비슷하게 / 같게'],['B','B가 더 많이']].map(([v,t])=>`<label><input type="radio" name="prediction" value="${v}" ${prediction===v?'checked':''}> ${t}</label>`).join('')}</div><p class="note">예상에는 점수를 매기지 않습니다. 이 응답 한 쌍의 결과는 전체 실험의 경향과 다를 수 있습니다.</p><div class="actions"><button class="primary" id="reveal">실제 응답 비교하기</button></div></div><div id="comparison"></div></section></div>`;
 document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{current=+b.dataset.case;stage=0;prediction='';guesses=[[],[]];shown=false;renderLab();});
 document.querySelectorAll('[name=prediction]').forEach(r=>r.onchange=()=>{prediction=r.value;});
 $('#reveal').onclick=()=>{if(!prediction){notify('먼저 예상 하나를 선택해 주세요.');return;}stage=1;renderComparison();$('#comparison').scrollIntoView({behavior:'instant',block:'start'});};
 if(current===0&&!stage){const hint=document.createElement('div');hint.className='guide';hint.innerHTML='<strong>첫 실험 · 먼저 이것만 해 보세요</strong><p>① 공통 요구사항을 펼쳐 읽기 → ② A와 B의 입력 프롬프트 비교 → ③ 예상 하나를 고르고 실제 응답 열기</p><small>A·B는 같은 과제를 서로 다른 방식으로 요청한 응답입니다. C00·C04 같은 표기는 연구 조건 번호이므로 외울 필요가 없습니다.</small>';$('#comparison').before(hint);} if(stage)renderComparison();
}
function renderComparison(){const c=DATA.cases[current];
 $('#comparison').innerHTML=`<div class="section-title"><h2>응답이 어긴 조건을 찾아보세요</h2><span class="tag">저장된 실제 응답</span></div><p class="note">A와 B를 각각 읽고, 지키지 않은 조건에만 체크하세요. 모두 지켰다면 아무것도 체크하지 않아도 됩니다. 아래 ‘검사 결과와 비교’를 누르면 내 판단과 앱 판정을 함께 볼 수 있습니다.</p><div class="pair">${c.items.map((x,j)=>`<article class="card"><h3>${j?'B':'A'} · ${esc(x.name)}</h3><div class="response">${esc(x.response)}</div><div class="checklist">${DATA.rules.map((r,i)=>`<label class="rule"><input type="checkbox" data-side="${j}" data-rule="${i}" ${guesses[j].includes(i)?'checked':''} ${shown?'disabled':''}><span>${i+1}. ${esc(r)}</span></label>`).join('')}</div></article>`).join('')}</div><div class="actions"><button class="primary" id="check">${shown?'판정 다시 보기':'검사 결과와 비교'}</button></div><div id="feedback"></div>`;
 document.querySelectorAll('[data-rule]').forEach(b=>b.onchange=()=>{const j=+b.dataset.side,i=+b.dataset.rule;guesses[j]=b.checked?[...guesses[j],i]:guesses[j].filter(x=>x!==i);});
 $('#check').onclick=()=>{shown=true;renderComparison();$('#feedback').scrollIntoView({behavior:'instant',block:'start'});};if(shown)renderFeedback();
}
function renderFeedback(){const c=DATA.cases[current];let correct=0,total=0;let found=0,violations=0,falseAlarms=0; c.items.forEach((x,j)=>analyze(x.response).flags.forEach((f,i)=>{if(f===false){violations++;if(guesses[j].includes(i))found++;}if(f===true&&guesses[j].includes(i))falseAlarms++;}));
 const rows=DATA.rules.map((r,i)=>{const cells=c.items.map((x,j)=>{const f=analyze(x.response).flags[i];if(f!==null){total++;if(guesses[j].includes(i)===!f)correct++;}const diff=f!==null&&f!==x.checks[i];return `<td class="${f===null?'':f?'good':'bad'}">${f===null?'확인 필요':f?'준수':'위반'}${diff?'<br><small>원채점과 다름</small>':''}<br><small>내 판단: ${guesses[j].includes(i)?'위반':'준수'}</small></td>`;});return `<tr><td>${i+1}. ${esc(r)}</td>${cells.join('')}</tr>`;}).join('');
 $('#feedback').innerHTML=`<div class="card"><span class="eyebrow">내 답과 실험 결과 비교하기</span><h2>${esc(c.title)}</h2><p>${esc(c.lesson)}</p><div class="result"><strong>위반 발견: ${found} / ${violations}개 · 잘못 표시: ${falseAlarms}개</strong><p class="note">앱의 판정을 기준으로, 놓치지 않고 찾은 위반과 잘못 표시한 항목을 셉니다. 아무것도 체크하지 않으면 발견한 위반은 0개입니다. 이 숫자는 학습 성적이 아닙니다.</p></div><div class="tablewrap"><table><thead><tr><th>앱 보완 판정</th><th>A</th><th>B</th></tr></thead><tbody>${rows}</tbody></table></div><details><summary>원논문 채점과 보완 판정의 차이</summary><p>원채점 준수: A ${c.items[0].checks.filter(Boolean).length}/8, B ${c.items[1].checks.filter(Boolean).length}/8. 아래 집계는 원채점 기준입니다.</p><p>앱은 Q.·A. 표지를 문장 구분점으로 세지 않습니다. 종결 부호 없는 본문은 임의로 제외하지 않고 관련 항목을 ‘확인 필요’로 표시합니다. 해요체는 문장 끝 ‘요’ 검사이며 의미·사실성은 판단하지 않습니다.</p><p class="note">현재 보완 판정도 한국어 문장의 완전한 분석기가 아닙니다. 인용문·약어 등 복잡한 표현은 사람이 확인해야 합니다.</p></details><h3>이 사례 한 쌍과 전체 실험을 구분하세요</h3><div class="pair">${c.aggregate.map(r=>`<div class="result"><small>${esc(r['조건명'])} · ${esc(r['짝 수'])}쌍</small><div class="score">${esc(r['준수율(%)'])}%</div><small>조건별 평균 규칙 준수율</small><div class="bar"><i style="width:${Number(r['준수율(%)'])}%"></i></div></div>`).join('')}</div><p class="note">비교할 차이가 드러나는 사례를 골랐습니다. 무작위로 뽑은 표본은 아닙니다. 위 수치는 전체 조건을 모두 지킨 응답의 비율과 다르며, 서로 다른 실험의 수치를 합쳐 해석하면 안 됩니다.</p><details><summary>원자료 출처</summary><p class="source">${esc(c.source)} · ${esc(c.task)}<br>${esc(c.aggregateSource)}</p><p class="note">실제 프롬프트·응답을 원자료에서 추출했습니다. 응답 해시는 실행 ZIP의 evidence.json에서 확인할 수 있습니다.</p></details><label class="field" for="reflection">다음에 무엇을 다르게 하겠나요?</label><textarea id="reflection" maxlength="3000" placeholder="예: 예시를 붙이기 전에 지시와 말투가 충돌하는지 확인하겠습니다.">${esc(saved.cases[c.id]?.reflection||'')}</textarea><div class="actions"><button class="primary" id="savecase">학습 기록 저장</button><button id="apply">다른 과제에 적용하기 →</button>${current<5?'<button id="next">다음 사례</button>':''}</div></div>`;
 $('#savecase').onclick=()=>{const reflection=$('#reflection').value.trim();if(!reflection){notify('관찰하거나 바꿀 점을 한 줄 적어 주세요.');return;}saved.cases[c.id]={id:c.id,title:c.title,prediction,guesses:guesses.map(a=>[...a]),correct,total,found,violations,falseAlarms,reflection,date:new Date().toISOString()};if(persist())notify('학습 기록을 저장했습니다.');};
 $('#apply').onclick=()=>go('editor');if($('#next'))$('#next').onclick=()=>{current++;stage=0;shown=false;prediction='';guesses=[[],[]];renderLab();window.scrollTo(0,0);};
}
function renderEditor(){const d=saved.draft||{};
 $('#main').innerHTML=hero('프롬프트 작성 연습','논문에서 쓴 형식으로 빈 틀을 만들어 보세요.','이 연습에서는 논문에서 사용한 8개 조건을 따릅니다. 모든 프롬프트에 필요한 형식은 아닙니다. 표나 목록을 만드는 연습은 학습 과정 7·8차시에 있습니다.')+`<div class="pair"><section class="card"><span class="tag">새 연습 과제 · 논문 실험 대상 아님</span><h2>동네 수리 모임 초대문</h2><p>토요일 오후 2시, 마을회관에서 작은 가전 수리 모임을 엽니다. 참가비는 무료이고 고장 난 물건 한 개를 가져옵니다. 아래 8가지 공통 형식 조건을 지키도록 프롬프트를 준비해 보세요.</p><details><summary>요구사항 8개</summary><ol>${DATA.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ol></details><label class="field" for="task">내 과제 설명</label><textarea id="task" maxlength="6000">${esc(d.task||'토요일 오후 2시 마을회관에서 열리는 무료 가전 수리 모임 초대문을 작성해 줘. 고장 난 물건 한 개를 가져오도록 안내해 줘.')}</textarea><h3>문단별 문장 수</h3><p class="note">4개 문단에 들어갈 문장 수를 정하세요. 첫 문단 2개, 각 문단 2~4개, 전체 10~14개가 목표입니다.</p><div class="row">${[2,3,3,2].map((v,i)=>`<div><label class="field" for="n${i}">${i+1}문단</label><input id="n${i}" type="number" min="1" max="8" value="${v}"></div>`).join('')}</div><div class="actions"><button id="make">빈 틀 만들기</button></div><label class="field" for="template">빈 틀 · 직접 수정할 수 있습니다</label><textarea id="template" class="large" maxlength="12000">${esc(d.template||'')}</textarea><div class="actions"><button id="inspect">틀 점검</button></div><div id="inspection" role="status"></div></section><section class="card"><h2>예시의 충돌을 고쳐 보세요</h2><p>요구사항은 해요체입니다. 다음 예시의 말투가 요구와 맞는지 확인하고 수정하세요.</p><label class="field" for="example">예시 문장</label><textarea id="example" maxlength="3000">${esc(d.example||'토요일에 모임을 엽니다. 고장 난 물건을 가져오십시오.')}</textarea><label class="field" for="strategy">내가 선택한 방법</label><select id="strategy"><option value="skeleton">빈 형식 틀 제공</option><option value="example">수정한 예시와 형식 틀 제공</option><option value="plain">지시만 제공</option></select><label class="field" for="reason">이 방법을 고른 이유와 걱정되는 점</label><textarea id="reason" maxlength="3000" placeholder="왜 이 방법을 골랐나요? 그래도 AI가 놓칠 수 있는 조건이 있나요?">${esc(d.reason||'')}</textarea><div class="actions"><button class="primary" id="compose">수정안 만들기</button><button id="savedraft">연습 저장</button></div><div id="draftfeedback" role="status"></div><label class="field" for="output">수정안 · 생성 결과 아님</label><textarea id="output" class="large" readonly placeholder="수정안 만들기를 누르면 여기에 표시됩니다."></textarea><div class="actions"><button id="exportprompt">수정안 TXT 내려받기</button></div><p class="note">여기서는 프롬프트만 만듭니다. AI 응답을 받으려면 ‘나의 실험’으로 이동하세요.</p></section></div>`;
 $('#strategy').value=d.strategy||'skeleton';
 const make=()=>{const ns=[0,1,2,3].map(i=>Number($('#n'+i).value));if(ns.some(n=>!Number.isInteger(n)||n<1||n>8)){notify('문단별 슬롯 수는 1~8 사이 정수로 입력해 주세요.');return;}$('#template').value=ns.map((n,i)=>'▶ [소제목 '+(i+1)+']\n'+Array.from({length:n},(_,j)=>`[${i+1}-${j+1} 문장]${i===2&&j===1?'!':'.'}`).join(' ')).join('\n\n');};
 if(!d.template)make();$('#make').onclick=make;
 function inspect(){const t=$('#template').value;const a=analyze(t);const flags=a.flags.slice(0,6);$('#inspection').innerHTML=`<div class="result">${flags.map((v,i)=>`<div>${i+1}. ${esc(DATA.rules[i])}: <strong>${v===null?'확인 필요':v?'구조 충족':'구조 조정 필요'}</strong></div>`).join('')}<p class="note">빈칸에는 아직 실제 문장이 들어 있지 않습니다. 내용을 채운 뒤 말투와 첫 문장의 길이, 원래 정보가 바뀌지 않았는지 확인하세요.</p></div>`;return flags;}
 $('#inspect').onclick=inspect;
 const read=()=>({task:$('#task').value.trim(),template:$('#template').value.trim(),example:$('#example').value.trim(),reason:$('#reason').value.trim(),strategy:$('#strategy').value,date:new Date().toISOString()});
 $('#compose').onclick=()=>{const v=read();if(!v.task){notify('과제 설명을 입력해 주세요.');return;}if(v.strategy!=='plain'&&!v.template){notify('형식 틀을 입력해 주세요.');return;}if(v.strategy==='example'&&!v.example){notify('수정한 예시를 입력해 주세요.');return;}
 const conflict=/(합니다|엽니다|십시오|습니다|입니다)/.test(v.example);const f=inspect();
 $('#draftfeedback').innerHTML=`<div class="result ${v.strategy==='example'&&conflict?'warning':''}">${v.strategy==='example'&&conflict?'예시에 합니다체 표현이 남아 있습니다. 해요체 요구와의 충돌을 확인하세요.':v.strategy==='example'?'단순 패턴 검사에서는 합니다체 표현을 찾지 못했습니다. 전체 문체는 직접 확인하세요.':'예시 문장은 수정안에 포함하지 않았습니다.'}<p>${v.strategy!=='plain'&&f.some(x=>x!==true)?'형식 틀에 조정하거나 확인할 항목이 있습니다.':'실제 응답의 준수를 보장하는 판정은 아닙니다.'}</p></div>`;
 $('#output').value=v.task+'\n\n요구사항:\n'+DATA.rules.map((r,i)=>(i+1)+'. '+r).join('\n')+(v.strategy!=='plain'?'\n\n출력 형식 틀(대괄호는 실제 내용으로 교체):\n'+v.template:'')+(v.strategy==='example'?'\n\n말투 참고 예시(전체 구조 예시가 아님):\n'+v.example:'');};
 $('#savedraft').onclick=()=>{const v=read();if(!v.task||!v.reason){notify('과제와 선택 이유를 입력해 주세요.');return;}saved.draft=v;if(persist())notify('적용 연습을 저장했습니다.');};
 $('#exportprompt').onclick=()=>{if(!$('#output').value){notify('먼저 수정안을 만들어 주세요.');return;}download('prompt-draft.txt',$('#output').value);};
}
function renderRecords(){const records=Object.values(saved.cases);$('#main').innerHTML=hero('비교·틀 기록','예상이 어떻게 바뀌었나요?','이 화면은 비교 실험과 원실험 틀 연습의 기록입니다. 8차시 답안은 ‘학습 과정’, 평가 결과는 ‘배움 확인’, API 실험은 ‘나의 실험’에서 확인하세요.')+`<div class="card"><div class="section-title"><h2>비교 실험 ${records.length} / 6 기록</h2><div class="actions"><button id="exportrecords">전체 기록 JSON</button><button id="clear">비교·틀 연습 기록 삭제</button></div></div><p class="note">${storageOK?'이 브라우저에 저장됩니다. 다른 기기와 동기화되지 않습니다.':'저장이 제한되어 현재 화면의 기록만 유지될 수 있습니다. 파일로 내려받으세요.'}</p>${records.length?records.map(r=>`<article class="result"><h3>0${esc(r.id)} · ${esc(r.title)}</h3><small>예상: ${esc(r.prediction)} · ${r.found!==undefined?'위반 발견 '+esc(r.found)+'/'+esc(r.violations)+' · 잘못 표시 '+esc(r.falseAlarms):'이전 방식의 기록 · 학습 점수로 해석하지 않음'}</small><p style="white-space:pre-wrap">${esc(r.reflection)}</p></article>`).join(''):'<div class="empty">아직 저장한 기록이 없습니다.<br>비교 실험을 마친 뒤 관찰을 한 줄 남겨 보세요.</div>'}</div>${saved.draft?`<div class="card"><h2>프롬프트 작성 기록</h2><p>${esc(saved.draft.task)}</p><p><strong>선택 이유</strong><br>${esc(saved.draft.reason)}</p><button id="editdraft">수정안 이어서 편집</button></div>`:''}`;
 $('#exportrecords').onclick=()=>download('prompt-lab-records.json',JSON.stringify({schema:'prompt-lab-backup-3',exported:new Date().toISOString(),state:saved},null,2),'application/json');$('#clear').onclick=()=>{if(confirm('이 브라우저의 비교 기록과 적용 연습을 삭제할까요?')){saved={cases:{},draft:null,onboardingVersion:saved.onboardingVersion,course:saved.course,course20:saved.course20,learningV3:saved.learningV3,learningArchives:saved.learningArchives};persist();renderRecords();}};if($('#editdraft'))$('#editdraft').onclick=()=>go('editor');}
function renderAbout(){$('#main').innerHTML=hero('이 앱의 바탕이 된 연구','논문의 결과를 어떻게 활용했나요?','논문에서 확인한 결과와 이 앱에서 연습하는 내용을 정리했습니다. 각 사례의 원자료도 확인할 수 있습니다.')+`<div class="card"><h2>${esc(DATA.title)}</h2><div class="tablewrap"><table><thead><tr><th>연구의 관찰</th><th>앱의 활동</th></tr></thead><tbody><tr><td>예시를 넣었을 때 형식 조건을 더 잘 지킴</td><td>동일 과제의 지시만 / 예시 추가 비교</td></tr><tr><td>내용을 비운 틀에서도 개선이 나타남</td><td>문장 수에 맞춰 빈 틀 만들기</td></tr><tr><td>일부 모델은 예시의 말투에 영향을 받음</td><td>충돌 발견 및 수정</td></tr><tr><td>모델·조건별 효과 차이</td><td>동점·악화·충돌 저항 사례 함께 보기</td></tr></tbody></table></div><h3>해석의 범위</h3><p>한국어 글쓰기 과제와 연구 당시 모델·설정에서 얻은 결과입니다. 현재의 모든 AI나 모든 작업에 같은 효과가 난다고 주장하지 않습니다. 빈 틀과 예시의 효과가 같은지, 앱으로 실력이 늘거나 작업 시간이 줄어드는지는 아직 확인하지 않았습니다.</p><h3>원채점과 앱 판정</h3><p>집계 수치는 원논문 CSV를 그대로 사용합니다. 앱은 문장 표지 Q.·A.를 보완 처리하고, 문장 종결이 불명확한 본문을 ‘확인 필요’로 표시합니다. 원채점은 수정하지 않으며 양쪽 판정이 다르면 비교 화면에 표시합니다. 내용 정확성·날짜·사실 보존은 자동 평가하지 않습니다.</p><h3>데이터와 개인정보</h3><p>선택한 12개 응답과 프롬프트, 관련 집계만 포함했습니다. 학습 과정에는 API가 필요 없습니다. ‘나의 실험’에서 실행하면 입력한 프롬프트를 OpenAI로 전송합니다. 작성한 학습 기록은 브라우저 저장소에 남으며 직접 내려받거나 삭제할 수 있습니다.</p><details><summary>원자료 식별</summary><p>T10파일.zip</p><p class="source">SHA-256: ${esc(DATA.sourceSHA256)}</p>${DATA.cases.map(c=>`<p class="source">사례 ${c.id}: ${esc(c.source)} · ${esc(c.task)} · ${esc(c.items.map(x=>x.condition).join(' / '))}</p>`).join('')}</details></div>`;}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
$('.brand').onclick=e=>{e.preventDefault();go('course');};
render();

// First-run guide: native dialog provides focus containment and Escape handling.
let onboardStep=0, onboardAnswer=null, onboardReturnFocus=null;
function openOnboarding(){
 onboardStep=0;onboardAnswer=null;onboardReturnFocus=document.activeElement;
 drawOnboarding();$('#onboarding').showModal();$('#onboard-title').focus();
}
function closeOnboarding(){
 saved.onboardingVersion=3;persist();$('#onboarding').close();
 if(onboardReturnFocus&&typeof onboardReturnFocus.focus==='function')onboardReturnFocus.focus();
}
function drawOnboarding(){
 const titles=['이런 답을 받고, 다시 고쳐 달라고 한 적 있나요?','먼저 요청 자체를 확인해 볼까요?','어떤 방법으로 전달하면 좋을까요?','앱에서는 이렇게 연습합니다','다음에 AI를 쓸 때, 무엇이 달라지면 좋을까요?'];
 const nextLabels=['왜 이런 일이 생길까요?','무엇을 확인하면 될까요?','앱에서는 어떻게 배우나요?','어떤 변화를 기대하나요?','학습 과정으로 가기'];
 const panels=[
 `<p>두 문장으로 써 달라고 했는데 세 문장이 나오거나, 부탁한 말투와 다른 답을 받은 적 있나요?</p><div class="practice-card"><span class="tag">설명용 예시</span><p><strong>내 요청</strong></p><blockquote>“모임 안내를 <strong>두 문장</strong>으로, ‘~요’로 끝나게 써 줘.”</blockquote><p><strong>받은 답</strong></p><div class="response">토요일에 모임을 엽니다.<br>장소는 도서관입니다.<br>책 한 권을 지참하십시오.</div><button id="onboard-reveal" aria-expanded="${!!onboardAnswer}">빠뜨린 조건 살펴보기</button><div role="status">${onboardAnswer?'<div class="result"><strong>문장 수와 말투가 요청과 다릅니다.</strong><p>두 문장을 요청했는데 세 문장입니다. 해요체를 요청했지만 합니다체로 작성됐습니다.</p></div>':''}</div></div><p>“좀 더 잘 써 줘”라고 반복하기 전에, <strong>어떤 조건을 어겼는지 먼저 확인해야</strong> 합니다.</p>`,
 `<p>원하는 답이 안 나왔다면, 요청한 조건부터 확인하세요.</p><div class="practice-card"><p><strong>“두 문단, 문단마다 두 문장, 전체 다섯 문장으로 써 줘.”</strong></p><p>두 문단에 두 문장씩이면 네 문장입니다. 이 요청은 예시를 더 붙여도 해결되지 않습니다. 어떤 조건을 우선할지 먼저 정해야 합니다.</p></div><p>조건끼리 모순이 없다면 다음은 전달 방법입니다. 지시만으로 충분할지, 예시나 빈 틀이 도움이 될지 살펴보세요. 예시를 쓸 때는 지시와 말투·형식이 맞는지도 확인합니다.</p><p class="note">논문은 지시·예시·빈 틀에 따른 지시 준수 차이를 다뤘습니다. 여기서는 그 결과를 바탕으로 요청을 점검하는 순서를 연습합니다.</p>`,
 `<div class="onboard-flow"><div><b>요청</b><span>‘잘 써 줘’를 넘어, 반드시 지켜야 할 조건이 분명한가?</span></div><div><b>방법 선택</b><span>지시만으로 시작할까? 예시나 빈 틀이 더 필요한가?</span></div><div><b>결과</b><span>실제로 조건을 지켰는가? 문장이 자연스러운 것만 보고 넘어가지 않았는가?</span></div></div><div class="practice-card"><strong>앞의 요청을 정리하면</strong><p>“첫 문장은 일시와 장소, 둘째 문장은 준비물을 알려 줘. 총 두 문장, 모두 해요체로 써 줘.”</p><p><strong>필요하다면 이런 빈 틀을 줄 수 있어요.</strong></p><div class="response">[일시·장소를 알리는 문장].<br>[준비물을 알리는 문장].</div></div><p>완성 예시를 더 붙이는 것만이 방법은 아닙니다. <strong>지시만 쓸지, 빈 틀이나 예시를 더할지</strong> 목적에 맞게 선택하고 결과를 확인하는 법을 배웁니다.</p>`,
 `<p><strong>총 8차시</strong> 동안 응답을 비교하고, 직접 프롬프트를 쓰고 고칩니다.</p><div class="onboard-flow"><div><b>1–2차시</b><span>확인할 조건을 정하고, 지시·예시·빈 틀 중 필요한 방법을 고릅니다.</span></div><div><b>3–4차시</b><span>조건의 모순이나 예시의 충돌을 찾고, 같은 기준으로 응답을 검사합니다.</span></div><div><b>5–6차시</b><span>빈 틀의 효과를 비교하는 실험을 짜고, 모델마다 결과가 다른지 살펴봅니다.</span></div><div><b>7–8차시</b><span>새 과제의 프롬프트를 직접 쓰고, 며칠 뒤 다시 풀어 봅니다.</span></div></div><p>각 차시에서 <strong>초안 쓰기 → 해설과 비교하기 → 고치고 이유 적기</strong>를 남깁니다. 설명을 읽은 뒤 무엇을 바꾸었는지까지 확인합니다.</p><p class="note">논문은 예시·골격·충돌·모델 차이의 근거를 제공합니다. 새 과제와 교육 과정은 그 결과를 바탕으로 설계한 학습 활동입니다.</p>`,
 `<div class="onboard-flow"><div><b>이전</b><span>“원하는 답이 아니네. 다시 잘 써 달라고 해야겠다.”</span></div><div><b>배운 뒤의 목표</b><span>“두 문장이라는 조건을 놓쳤네. 빈 틀을 더한 뒤 같은 조건으로 비교해 보자.”</span></div></div><p>기대하는 변화는 <strong>어긴 조건을 찾고, 프롬프트를 고친 뒤 결과를 확인하는 습관</strong>입니다. 반복해서 부탁하는 부담을 줄이는 데 도움이 되는지는 실제 작업에서 확인해야 합니다.</p><p class="note">이 앱으로 실력이 얼마나 늘거나 시간이 얼마나 줄어드는지는 아직 확인하지 않았습니다. ‘나의 실험’에서 실제 응답을 받아 고친 프롬프트의 효과를 비교할 수 있습니다. API 실행에는 별도 비용이 듭니다.</p><div class="practice-card"><h3>오늘은 1차시부터 시작하세요.</h3><p>먼저 짧은 안내문의 조건 위반을 판단하고 직접 고쳐 봅니다. 배우기 전 실력을 확인하려면 과정 화면에서 사전 평가부터 시작하세요. 여러 날에 나누어 이어가도 됩니다.</p><p class="note">차시당 목표 약 20분 · 추가 탐구는 선택 · 답안 자동 저장 · 과정 화면에서 백업 가능<br>상단 ‘처음 사용 안내’에서 언제든 이 이야기를 다시 볼 수 있습니다.</p></div>`
 ];
 $('#onboard-content').innerHTML=`<div class="onboard-top"><span class="eyebrow">왜 이걸 배우나요? · ${onboardStep+1} / ${panels.length}</span><button id="onboard-skip">안내 닫기</button></div><div class="onboard-progress" aria-hidden="true">${panels.map((_,i)=>`<span class="${i<=onboardStep?'filled':''}"></span>`).join('')}</div><h2 id="onboard-title" tabindex="-1">${titles[onboardStep]}</h2>${panels[onboardStep]}<div class="onboard-actions">${onboardStep?'<button id="onboard-prev">이전</button>':'<span></span>'}<button id="onboard-next" class="primary">${nextLabels[onboardStep]}</button></div>`;
 $('#onboard-skip').onclick=closeOnboarding;
 if(onboardStep)$('#onboard-prev').onclick=()=>{onboardStep--;drawOnboarding();$('#onboarding').scrollTop=0;$('#onboard-title').focus();};
 $('#onboard-next').onclick=()=>{if(onboardStep===panels.length-1){closeOnboarding();go('course');return;}onboardStep++;drawOnboarding();$('#onboarding').scrollTop=0;$('#onboard-title').focus();};
 if(onboardStep===0)$('#onboard-reveal').onclick=()=>{onboardAnswer=true;drawOnboarding();$('#onboard-reveal').focus();};
}
$('#help').onclick=openOnboarding;
$('#onboarding').addEventListener('cancel',e=>{e.preventDefault();closeOnboarding();});
if(saved.onboardingVersion!==3)openOnboarding();
